pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Admissible domain: owner calls, receiver non-zero, amount non-negative (include zero)
        vm.assume(receiver != address(0));
        // Restrict amount to avoid overflow issues; zero is explicitly allowed
        bound(amount, 0, 1e36);
        // Use the contract itself as sender (owner)
        vm.prank(address(c));
        vm.assume(msg.sender == address(c));
        // The reference expects amount > 0, so we check revert behavior:
        // Reference: amount == 0 -> revert; amount > 0 -> success.
        // Buggy: amount == 0 -> success (no revert).
        // Therefore, for any admissible input, if amount == 0, the call must revert.
        // If amount > 0, it must succeed.
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The invariant: the call reverts iff amount == 0
        // This holds for the reference (reverts on 0) but the buggy version passes for 0 (ok=true, breaking the rule).
        assertTrue((amount == 0) != ok);
    }
}

