pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // 1. Admissible domain: sender is owner, amount > 0, receiver != address(0)
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, address(c).balance);
        // Ensure the owner has enough Ether to send
        address owner = address(c).balance == 0 ? address(0) : address(c).balance;
        // We must find the owner address. It's a public variable, so there's a getter (owner())
        // Pre-fund the contract to have enough balance for the transfer
        vm.deal(address(c), amount);
        // 2. Adversarial counterparty: The difference is simply where Ether goes.
        // To observe the destination, we record the balance of the intended receiver before and after.
        // The reference sends to receiver; the mutant sends to a constant address (0x123).
        // Therefore, for any receiver != 0x123, the receiver's balance should increase by amount.
        // We need to ensure receiver != 0x123 so the distinction is clear.
        vm.assume(receiver != address(0x123));
        uint256 balBefore = receiver.balance;
        vm.prank(address(uint160(address(c)).balance == 0 ? 0 : 0)); // owner is the deployer (msg.sender in constructor)
        // The owner is the account that deployed C. We are the test contract, so owner is address(this)?
        // Wait, setUp deploys c, so owner = address(this). We need to prank as address(this).
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        uint256 balAfter = receiver.balance;
        // 3. Assert: the intended receiver's balance increases by amount
        assertTrue(balAfter - balBefore == amount);
    }
}

